/* Súper La Muñeca PRO Firebase — punto de venta e inventario por código de barras. */
'use strict';
const DB_KEY='slm:firebase:db:v3';
const EMPTY=()=>({version:1,products:[],inventoryLogs:[],sales:[],customers:[],customerMoves:[],suppliers:[],supplierMoves:[],orders:[],expenses:[],cashSessions:[],cashMovements:[]});
function load(){try{const raw=localStorage.getItem(DB_KEY);if(!raw)return EMPTY();const v=JSON.parse(raw);return validDb(v)?v:EMPTY()}catch(e){console.warn('No se pudo leer el respaldo local',e);return EMPTY()}}
const arrayFields=['products','inventoryLogs','sales','customers','customerMoves','suppliers','supplierMoves','orders','expenses','cashSessions','cashMovements'];
function validDb(v){return v&&typeof v==='object'&&v.version===1&&arrayFields.every(k=>Array.isArray(v[k]))}
let db=load(),tab='home',debtTab='customers',orderTab='pending',filterProducts='',sellFilter='',cart={},orderDraft=[],scanner=null,scanBusy=false,scanMode='inventory';
const el=id=>document.getElementById(id);
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(Number(v)||0);
const num=v=>Number.isFinite(Number(v))?Math.round(Number(v)*100)/100:0;
const uid=()=>globalThis.crypto?.randomUUID?.()||('id'+Date.now()+Math.random().toString(36).slice(2,9));
const now=()=>new Date().toISOString();
const localDay=(d=new Date())=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const dayOf=iso=>{const d=new Date(iso);return localDay(d)};
const datePretty=iso=>{if(!iso)return 'Sin fecha';const d=new Date(iso.length===10?iso+'T12:00:00':iso);return Number.isNaN(d.getTime())?String(iso):d.toLocaleDateString('es-MX',{day:'numeric',month:'short',year:'numeric'})};
const timePretty=iso=>new Date(iso).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'});
const byId=(arr,id)=>arr.find(x=>x.id===id);
const product=id=>byId(db.products,id),customer=id=>byId(db.customers,id),supplier=id=>byId(db.suppliers,id);
function save(){try{localStorage.setItem(DB_KEY,JSON.stringify(db));if(typeof cloudSave==='function')cloudSave();return true}catch(e){console.error(e);toast('No se pudo guardar. Exporta un respaldo.',true);return false}}
function toast(msg,isError=false){el('toastRoot').innerHTML=`<div class="toast ${isError?'error':''}">${h(msg)}</div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el('toastRoot').innerHTML='',3300)}
function go(next){tab=next;filterProducts='';sellFilter='';render();window.scrollTo({top:0,behavior:'instant'})}
function noData(icon,title,desc,act='',label=''){return `<div class="empty"><span class="empty-icon">${icon}</span><strong>${h(title)}</strong><p>${h(desc)}</p>${act?`<button class="btn btn-primary" data-act="${act}">${h(label)}</button>`:''}</div>`}
function header(eyebrow,title,sub=''){return `<div class="hello"><div><div class="eyebrow">${h(eyebrow)}</div><h1 class="title">${h(title)}</h1>${sub?`<p class="subtitle">${h(sub)}</p>`:''}</div></div>`}
function sum(arr,get=x=>x){return arr.reduce((s,x)=>s+num(get(x)),0)}
const openSession=()=>db.cashSessions.find(x=>!x.closedAt);
function cashExpected(session){return num(session.initial+sum(db.cashMovements.filter(m=>m.sessionId===session.id),x=>x.amount))}
function cashEvent(amount,kind,note){const s=openSession();if(!s)return false;db.cashMovements.push({id:uid(),sessionId:s.id,amount:num(amount),kind,note,at:now()});return true}
const todaySales=()=>db.sales.filter(s=>dayOf(s.at)===localDay());
const totalPending=()=>sum(db.orders.filter(o=>o.status==='pending'),o=>o.total);
const amountCustomer=()=>sum(db.customers,c=>c.debt);
const amountSupplier=()=>sum(db.suppliers,s=>s.debt);
const shortage=()=>db.products.filter(p=>p.stock<=p.minimum);
function render(){
  let html='';if(tab==='home')html=renderHome();if(tab==='sell')html=renderSell();if(tab==='inventory')html=renderInventory();if(tab==='debts')html=renderDebts();if(tab==='orders')html=renderOrders();el('screen').innerHTML=html;
  document.querySelectorAll('.nav-item').forEach(x=>{const active=x.dataset.tab===tab;x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});
}
function renderHome(){const sales=todaySales(),gross=sum(sales,s=>s.total),profit=sum(sales,s=>s.items.reduce((n,i)=>n+i.qty*(i.price-i.cost),0));const session=openSession(),low=shortage();const upcoming=db.orders.filter(o=>o.status==='pending').sort((a,b)=>a.arrivalDate.localeCompare(b.arrivalDate)).slice(0,3);
return `${header('MI NEGOCIO','Todo en orden 👋',datePretty(localDay())+' · Tu tienda en un solo lugar')}
<div class="card hero"><div class="hero-label">Ventas de hoy</div><div class="hero-value">${money(gross)}</div><div class="hero-foot"><span>${sales.length} ${sales.length===1?'venta':'ventas'} registradas</span><span>${sales.length?`Utilidad bruta aprox. ${money(profit)}`:'Empieza con tu primera venta'}</span></div></div>
<div class="grid-2"><div class="card stat"><div class="stat-k">Clientes me deben</div><div class="stat-v small">${money(amountCustomer())}</div><div class="stat-note">Fiados pendientes</div></div><div class="card stat"><div class="stat-k">Debo a proveedores</div><div class="stat-v small">${money(amountSupplier())}</div><div class="stat-note">Por pagar</div></div><div class="card stat"><div class="stat-k">Por recibir</div><div class="stat-v small">${money(totalPending())}</div><div class="stat-note">Costo estimado de pedidos</div></div><div class="card stat"><div class="stat-k">Productos bajos</div><div class="stat-v">${low.length}</div><div class="stat-note">Necesitan atención</div></div></div>
<div class="section-head"><h2>¿Qué quieres hacer?</h2></div>
<div class="quick-grid"><button class="quick" data-act="nav" data-tab="sell"><span class="quick-symbol">＋</span><span>Registrar venta ↗</span></button><button class="quick" data-act="scan"><span class="quick-symbol">▦</span><span>Escanear barras ↗</span></button><button class="quick" data-act="cash"><span class="quick-symbol">$</span><span>${session?'Ver mi caja':'Abrir caja'} ↗</span></button><button class="quick" data-act="new-order"><span class="quick-symbol">◈</span><span>Preparar pedido ↗</span></button></div>
<div class="section-head"><h2>Caja del día</h2><button class="link" data-act="cash">Administrar ›</button></div><div class="card"><div class="row-between"><div><div class="small muted">${session?'Efectivo esperado en caja':'Caja sin abrir'}</div><div class="stat-v">${session?money(cashExpected(session)):'—'}</div></div><span class="pill ${session?'':'warn'}">${session?'● Abierta':'Sin turno'}</span></div><p class="helper">${session?'Incluye fondo inicial, cobros en efectivo y salidas de dinero.':'Abre caja al empezar el día para registrar tus movimientos en efectivo.'}</p><button class="btn btn-outline btn-block" data-act="cash">${session?'Revisar movimientos y hacer corte':'Abrir caja'}</button></div>
${low.length?`<div class="section-head"><h2>Productos por surtir</h2><button class="link" data-act="nav" data-tab="inventory">Ver inventario ›</button></div><div class="list">${low.slice(0,4).map(p=>`<div class="list-row"><span class="item-icon">!</span><div class="grow"><div class="item-title">${h(p.name)}</div><div class="item-sub">Quedan ${p.stock} · mínimo ${p.minimum}</div></div><button class="btn btn-soft small-btn" data-act="stock" data-id="${p.id}">Surtir</button></div>`).join('')}</div>`:''}
${upcoming.length?`<div class="section-head"><h2>Próximas llegadas</h2><button class="link" data-act="nav" data-tab="orders">Ver pedidos ›</button></div><div class="list">${upcoming.map(o=>`<div class="list-row"><span class="item-icon">◈</span><div class="grow"><div class="item-title">${h(supplier(o.supplierId)?.name||'Proveedor')}</div><div class="item-sub">Llega ${datePretty(o.arrivalDate)}</div></div><span class="item-price">${money(o.total)}</span></div>`).join('')}</div>`:''}
${!db.products.length?`<div class="section-head"><h2>Primeros pasos</h2></div>${noData('▦','Empieza con tu inventario','Registra un producto y genera su código de barras para controlar las existencias.','new-product','Agregar primer producto')}`:''}`}
function renderInventory(){const items=db.products.filter(p=>`${p.name} ${p.code}`.toLowerCase().includes(filterProducts.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name,'es'));const totalCost=sum(db.products,p=>p.cost*p.stock);
return `${header('INVENTARIO','Mis productos','Escanea su código de barras, registra existencias y evita quedarte sin mercancía.')}
<div class="metric-strip"><div class="chip">Productos<strong>${db.products.length}</strong></div><div class="chip">Piezas en tienda<strong>${sum(db.products,p=>p.stock)}</strong></div><div class="chip">Valor a costo<strong>${money(totalCost)}</strong></div></div>
<div class="toolbar"><button class="btn btn-primary" data-act="new-product">＋ Producto</button><button class="btn btn-outline" data-act="scan">▥ Escanear barras</button></div>
<div class="search"><input id="inventorySearch" class="input" type="search" placeholder="Buscar producto o código…" value="${h(filterProducts)}" autocomplete="off" aria-label="Buscar productos"></div>
${items.length?`<div class="list">${items.map(p=>`<div class="list-row"><div class="item-icon">▦</div><div class="grow"><div class="item-title">${h(p.name)}</div><div class="item-sub">${h(p.code)} · <span class="${p.stock<=p.minimum?'orange':''}">${p.stock} disponibles</span></div></div><div style="text-align:right"><div class="item-price">${money(p.price)}</div><button class="link" data-act="product" data-id="${p.id}">Ver ›</button></div></div>`).join('')}</div>`:db.products.length?noData('⌕','Sin resultados','Prueba otra palabra o código.'):noData('▦','Aún no hay productos','Agrega tu primer producto y registra su código que podrás imprimir.','new-product','Agregar producto')}`}
function renderSell(){const found=db.products.filter(p=>`${p.name} ${p.code}`.toLowerCase().includes(sellFilter.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name,'es'));const entries=Object.entries(cart).filter(([id,q])=>product(id)&&q>0);const total=sum(entries,([id,q])=>product(id).price*q),units=sum(entries,([,q])=>q);
return `${header('PUNTO DE VENTA','Cobrar es fácil','Busca un producto, agrégalo y elige cómo te pagaron.')}
${!openSession()?`<div class="notice warning">La caja no está abierta. Puedes preparar una venta, pero para cobrar en efectivo primero tendrás que abrirla. <button class="link" data-act="cash">Abrir caja →</button></div>`:''}
<div class="toolbar" style="margin-bottom:0"><button class="btn btn-outline btn-block" data-act="scan-sale">▥ Escanear para vender</button></div><div class="search"><input id="sellSearch" class="input" type="search" placeholder="Buscar nombre o código de barras…" value="${h(sellFilter)}" autocomplete="off" aria-label="Buscar producto para venta"></div>
${db.products.length?`<div class="list">${found.slice(0,35).map(p=>`<div class="list-row"><div class="item-icon">▣</div><div class="grow"><div class="item-title">${h(p.name)}</div><div class="item-sub">${money(p.price)} · ${p.stock} disponibles</div></div><button class="action-compact" ${p.stock<=num(cart[p.id]||0)?'disabled':''} data-act="cart-add" data-id="${p.id}" aria-label="Agregar ${h(p.name)}">+</button></div>`).join('')}</div>`:noData('▦','Primero registra productos','El inventario es necesario antes de registrar ventas.','new-product','Agregar producto')}
${entries.length?`<div class="section-head"><h2>Tu venta (${units})</h2><button class="link" data-act="cart-clear">Vaciar</button></div><div class="card cart">${entries.map(([id,q])=>{const p=product(id);return `<div class="cart-line"><div class="grow"><div class="item-title">${h(p.name)}</div><div class="item-sub">${money(p.price*q)}</div></div><div class="stepper"><button data-act="cart-sub" data-id="${id}" aria-label="Quitar una unidad">−</button><b>${q}</b><button data-act="cart-add" data-id="${id}" ${q>=p.stock?'disabled':''} aria-label="Añadir una unidad">+</button></div></div>`}).join('')}<div class="total-row"><span>Total a cobrar</span><span class="total-amount">${money(total)}</span></div><button class="btn btn-primary btn-block" data-act="checkout">Cobrar ${money(total)} →</button></div>`:db.products.length?`<p class="helper" style="text-align:center;margin-top:20px">Toca + en los productos para comenzar una venta.</p>`:''}`}
function renderDebts(){const isClient=debtTab==='customers';const arr=isClient?db.customers:db.suppliers;const amount=sum(arr,x=>x.debt);return `${header('CUENTAS PENDIENTES','Deudas y fiados','Controla lo que te deben y lo que tienes que pagar.')}
<div class="switches"><button class="${isClient?'active':''}" data-act="debt-tab" data-kind="customers">Clientes me deben</button><button class="${!isClient?'active':''}" data-act="debt-tab" data-kind="suppliers">Debo a proveedores</button></div>
<div class="card"><div class="stat-k">${isClient?'Pendiente de cobrar':'Pendiente de pagar'}</div><div class="stat-v">${money(amount)}</div><div class="stat-note">${arr.filter(x=>x.debt>0).length} cuentas con saldo</div></div>
<div class="toolbar"><button class="btn btn-primary" data-act="${isClient?'new-customer':'new-supplier'}">＋ ${isClient?'Nuevo cliente':'Nuevo proveedor'}</button>${isClient?'<button class="btn btn-outline" data-act="payment-customer">Registrar abono</button>':'<button class="btn btn-outline" data-act="payment-supplier">Registrar pago</button>'}</div>
${arr.length?`<div class="list">${arr.slice().sort((a,b)=>b.debt-a.debt).map(x=>`<div class="list-row"><div class="item-icon">${isClient?'C':'P'}</div><div class="grow"><div class="item-title">${h(x.name)}</div><div class="item-sub">${x.phone?h(x.phone):'Sin teléfono'} · ${x.debt>0?'Saldo pendiente':'Al corriente'}</div></div><div style="text-align:right"><div class="item-price ${x.debt>0?'orange':'green'}">${money(x.debt)}</div><button class="link" data-act="${isClient?'customer':'supplier'}" data-id="${x.id}">Ver ›</button></div></div>`).join('')}</div>`:noData('⇄',isClient?'Sin clientes registrados':'Sin proveedores registrados',isClient?'Agrega a un cliente cuando le fíes productos.':'Registra tus proveedores para planear pedidos y controlar pagos.',isClient?'new-customer':'new-supplier',isClient?'Crear cliente':'Crear proveedor')}`}
function renderOrders(){const pending=db.orders.filter(o=>o.status==='pending').sort((a,b)=>a.arrivalDate.localeCompare(b.arrivalDate)),historical=db.orders.filter(o=>o.status!=='pending').sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),orders=orderTab==='pending'?pending:historical;
return `${header('COMPRAS','Pedidos y llegadas','Organiza lo que necesitas pedir, cuándo llega y cuánto gastarás.')}
<div class="card hero"><div class="hero-label">Dinero estimado para pedidos pendientes</div><div class="hero-value">${money(totalPending())}</div><div class="hero-foot"><span>${pending.length} pedidos por recibir</span><span>Sin incluir deudas anteriores</span></div></div>
<div class="toolbar"><button class="btn btn-primary btn-block" data-act="new-order">＋ Preparar pedido</button></div>
<div class="switches"><button class="${orderTab==='pending'?'active':''}" data-act="order-tab" data-kind="pending">Por llegar (${pending.length})</button><button class="${orderTab==='history'?'active':''}" data-act="order-tab" data-kind="history">Historial</button></div>
${orders.length?`<div class="list">${orders.map(o=>`<div class="list-row"><div class="item-icon">◈</div><div class="grow"><div class="item-title">${h(supplier(o.supplierId)?.name||'Proveedor')}</div><div class="item-sub">${o.status==='pending'?'Llega':'Registrado'} ${datePretty(o.status==='pending'?o.arrivalDate:(o.receivedAt||o.createdAt))} · ${o.items.length} producto(s)</div><div style="margin-top:4px"><span class="tag">${o.status==='pending'?'Por recibir':o.status==='received'?'Recibido':'Cancelado'}</span></div></div><div style="text-align:right"><div class="item-price">${money(o.total)}</div><button class="link" data-act="order" data-id="${o.id}">Ver ›</button></div></div>`).join('')}</div>`:noData('◈',orderTab==='pending'?'Sin pedidos pendientes':'Sin historial',orderTab==='pending'?'Prepara un pedido con productos, cantidades, costos y fecha estimada de llegada.':'Los pedidos que recibas o canceles aparecerán aquí.',orderTab==='pending'?'new-order':'',orderTab==='pending'?'Nuevo pedido':'')}
<div class="notice">Consejo: preparar un pedido <b>no aumenta el inventario ni crea deuda</b>. Eso sucede cuando confirmas que llegó la mercancía.</div>`}
function openModal(title,content,footer=''){closeScanner();el('modalRoot').innerHTML=`<div class="modal-overlay" role="presentation"><div class="sheet" role="dialog" aria-modal="true" aria-label="${h(title)}"><div class="drag-bar"></div><div class="sheet-head"><h2>${h(title)}</h2><button class="close-btn" data-act="close" aria-label="Cerrar">×</button></div>${content}${footer?`<div class="sheet-footer">${footer}</div>`:''}</div></div>`;document.body.style.overflow='hidden';const first=el('modalRoot').querySelector('input:not([type="file"]),select');if(first&&window.innerWidth>760)first.focus()}
function closeModal(){closeScanner();el('modalRoot').innerHTML='';document.body.style.overflow=''}
function field(label,id,type='text',value='',more=''){return `<label class="field"><span>${h(label)}</span><input class="input" id="${id}" type="${type}" value="${h(value)}" ${more}></label>`}
function selectField(label,id,options,first=''){return `<label class="field"><span>${h(label)}</span><select class="select" id="${id}">${first}${options.map(o=>`<option value="${h(o.id)}">${h(o.name)}</option>`).join('')}</select></label>`}
function inputVal(id){return el(id)?.value.trim()??''}
function positive(v,allowZero=false){return Number.isFinite(Number(v))&&(allowZero?Number(v)>=0:Number(v)>0)}
function needCash(method){if(method==='cash'&&!openSession()){toast('Abre caja antes de registrar movimientos en efectivo.',true);return false}return true}
function askNewProduct(p=null,prefill=''){openModal(p?'Editar producto':'Nuevo producto',`${field('Código de barras','pBarcode','text',p?.code||prefill,'maxlength="40" placeholder="Escanea o escribe el código EAN/UPC" inputmode="numeric" autocomplete="off"')}
<p class="helper">Usa el código de barras que ya trae el empaque. Si el producto no tiene, deja vacío y crearemos uno interno.</p>
${field('Nombre del producto *','pName','text',p?.name||'','maxlength="80" placeholder="Ej. Leche entera 1 litro"')}
<div class="form-grid">${field('Precio de compra *','pCost','number',p?.cost??'','min="0" step="0.01" inputmode="decimal"')}${field('Precio de venta *','pPrice','number',p?.price??'','min="0" step="0.01" inputmode="decimal"')}</div>
<div class="form-grid">${p?'':field('Cantidad inicial','pStock','number','0','min="0" step="1" inputmode="numeric"')}${field('Avisar cuando queden','pMin','number',p?.minimum??'3','min="0" step="1" inputmode="numeric"')}</div>
<div class="notice">${p?'Para cambiar existencias, utiliza «Sumar / restar».':'Podrás escanear el código desde la cámara o escribirlo manualmente cuando recibas mercancía.'}</div>`, `<button class="btn btn-primary btn-block" data-act="save-product" data-id="${p?.id||''}">${p?'Guardar cambios':'Guardar producto'}</button>`)}
function saveProduct(id){const name=inputVal('pName'),cost=num(inputVal('pCost')),price=num(inputVal('pPrice')),minimum=Number(inputVal('pMin')),stock=id?0:Number(inputVal('pStock'));let code=inputVal('pBarcode').replace(/\s+/g,'').toUpperCase();
if(!name||!positive(inputVal('pCost'),true)||!positive(inputVal('pPrice'),true)||!Number.isInteger(minimum)||minimum<0||(!id&&(!Number.isInteger(stock)||stock<0))){toast('Revisa nombre, precios y cantidades.',true);return}
if(code&&!/^[0-9A-Z.-]{4,40}$/.test(code)){toast('El código de barras contiene caracteres inválidos.',true);return}
if(!code){let idx=1;do{code='SLM-'+String(idx++).padStart(6,'0')}while(db.products.some(p=>p.code===code))}
if(db.products.some(p=>p.id!==id&&sameBarcode(p.code,code))){toast('Ya existe un producto con ese código de barras.',true);return}
if(id){const p=product(id);if(!p)return;Object.assign(p,{name,cost,price,minimum,code});save();closeModal();render();toast('Producto actualizado.')}else{const p={id:uid(),code,name,cost,price,stock,minimum};db.products.push(p);db.inventoryLogs.push({id:uid(),productId:p.id,qty:stock,reason:'Inventario inicial',at:now()});save();render();showBarcode(p.id);toast('Producto registrado.')}}
function showProduct(id){const p=product(id);if(!p)return;openModal(p.name,`<div class="card" style="box-shadow:none"><div class="row-between"><span class="muted small code">${h(p.code)}</span><span class="pill ${p.stock<=p.minimum?'warn':''}">${p.stock} unidades</span></div><div class="measure"><span class="muted small">Precio de venta</span><strong>${money(p.price)}</strong></div><div class="measure"><span class="muted small">Costo por pieza</span><strong>${money(p.cost)}</strong></div><div class="measure"><span class="muted small">Valor del inventario</span><strong>${money(p.cost*p.stock)}</strong></div></div>
<div class="section-head"><h2>Acciones rápidas</h2></div><div class="two-buttons"><button class="btn btn-primary" data-act="stock" data-id="${id}">＋ / − Existencias</button><button class="btn btn-outline" data-act="barcode" data-id="${id}">▥ Código de barras</button><button class="btn btn-soft" data-act="product-edit" data-id="${id}">Editar producto</button><button class="btn btn-soft" data-act="cart-direct" data-id="${id}">Añadir a venta</button></div>`)}
function sameBarcode(a,b){const v=String(a||'').trim().toUpperCase(),w=String(b||'').trim().toUpperCase();return v===w||(/^0\d{12}$/.test(v)&&v.slice(1)===w)||(/^0\d{12}$/.test(w)&&w.slice(1)===v)}
function showBarcode(id){const p=product(id);if(!p)return;openModal('Código de barras',`<div class="label-print"><div class="print-title">Súper La Muñeca</div><p class="bold" style="text-align:center;margin:8px 0 3px">${h(p.name)}</p><div class="barcode-stage"><svg id="barcodeRender" aria-label="Código de barras"></svg></div><div class="code" style="text-align:center;margin:12px">${h(p.code)}</div><div style="text-align:center" class="print-title">${money(p.price)}</div></div><p class="helper">Si el producto ya trae código de fábrica, utiliza ese. Las etiquetas son opcionales para productos sin código.</p>`,`<button class="btn btn-primary btn-block" data-act="print">Imprimir etiqueta</button>`);try{if(typeof JsBarcode==='function'){JsBarcode('#barcodeRender',p.code,{format:'CODE128',displayValue:true,background:'#ffffff',lineColor:'#111111',width:1.55,height:80,margin:10,fontSize:13});}else{el('barcodeRender').outerHTML='<div style="text-align:center;padding:32px">'+h(p.code)+'</div>';}}catch(e){console.warn(e);el('barcodeRender').outerHTML='<div>'+h(p.code)+'</div>'}}
function showQR(id){showBarcode(id)}
function stockModal(id){const p=product(id);if(!p)return;openModal('Actualizar inventario',`<div class="notice"><b>${h(p.name)}</b><br>Actualmente hay ${p.stock} unidades.</div>${field('¿Cuántas unidades?','stockQty','number','1','min="1" step="1" inputmode="numeric"')}<div class="two-buttons"><button class="btn btn-soft" data-act="change-stock" data-id="${id}" data-sign="1">＋ Entraron productos</button><button class="btn btn-danger" data-act="change-stock" data-id="${id}" data-sign="-1">− Salieron / merma</button></div><p class="helper">Para registrar una venta, usa «Vender». Este ajuste es para surtido, conteos o pérdidas, y no registra pagos.</p>`)}
function changeStock(id,sign){const p=product(id),qty=Number(inputVal('stockQty'));if(!p||!Number.isInteger(qty)||qty<1){toast('Escribe una cantidad válida.',true);return}if(p.stock+sign*qty<0){toast('No hay suficientes unidades.',true);return}p.stock+=sign*qty;db.inventoryLogs.push({id:uid(),productId:id,qty:sign*qty,reason:sign>0?'Entrada manual':'Salida / merma',at:now()});save();closeModal();render();toast('Existencias actualizadas.')}
function scannerModal(mode='inventory'){scanMode=mode;openModal(mode==='sell'?'Escanear para vender':'Escanear código de barras',`<div class="notice">Apunta la cámara al código de barras del empaque. Si no lo lee, puedes escribir sus números manualmente.</div><div class="scanner" id="qrReader"></div><button class="btn btn-primary btn-block" data-act="camera-start">▥ Activar cámara</button><div class="field"><span>¿No abre la cámara? Toma una foto</span><input type="file" id="scanPhoto" class="input" accept="image/*" capture="environment" aria-label="Tomar foto de código de barras"></div><div class="hr"></div>${field('Código de barras','scanText','text','','placeholder="7501234567890" inputmode="numeric" autocomplete="off"')}<button class="btn btn-outline btn-block" data-act="lookup-qr">Buscar producto</button><p class="helper">Si el código aún no existe, podrás registrar el producto. La cámara necesita HTTPS y permiso del navegador.</p>`)}
async function closeScanner(){const current=scanner;scanner=null;scanBusy=false;if(current)try{if(current.isScanning)await current.stop();await current.clear()}catch(e){console.debug('Scanner cerrado',e)}}
async function startCamera(){if(scanner)return;if(!window.isSecureContext){toast('La cámara necesita abrir la app desde HTTPS.',true);return}if(typeof Html5Qrcode==='undefined'){toast('La cámara necesita internet al abrir la app. Usa el código manual.',true);return}try{scanner=new Html5Qrcode('qrReader',{formatsToSupport:typeof Html5QrcodeSupportedFormats==='undefined'?undefined:[Html5QrcodeSupportedFormats.EAN_13,Html5QrcodeSupportedFormats.EAN_8,Html5QrcodeSupportedFormats.UPC_A,Html5QrcodeSupportedFormats.UPC_E,Html5QrcodeSupportedFormats.CODE_128,Html5QrcodeSupportedFormats.CODE_39,Html5QrcodeSupportedFormats.ITF]});scanBusy=false;await scanner.start({facingMode:'environment'},{fps:12,qrbox:{width:280,height:150}},async text=>{if(scanBusy)return;scanBusy=true;await closeScanner();lookupCode(text)},()=>{});toast('Cámara lista para escanear.')}catch(e){console.warn('No se pudo activar la cámara',e);await closeScanner();toast('No se pudo abrir la cámara. Revisa los permisos.',true)}}
async function scanFromPhoto(file){if(typeof Html5Qrcode==='undefined')return toast('No se pudo cargar el lector de códigos. Escribe el número manualmente.',true);try{await closeScanner();scanner=new Html5Qrcode('qrReader',{formatsToSupport:typeof Html5QrcodeSupportedFormats==='undefined'?undefined:[Html5QrcodeSupportedFormats.EAN_13,Html5QrcodeSupportedFormats.EAN_8,Html5QrcodeSupportedFormats.UPC_A,Html5QrcodeSupportedFormats.UPC_E,Html5QrcodeSupportedFormats.CODE_128,Html5QrcodeSupportedFormats.CODE_39,Html5QrcodeSupportedFormats.ITF]});const code=await scanner.scanFile(file,true);await closeScanner();lookupCode(code)}catch(err){console.error(err);await closeScanner();toast('No se pudo leer el código en la foto. Intenta con mejor iluminación.',true)}}
function lookupCode(raw){const code=String(raw||'').trim().toUpperCase();if(!code)return toast('Escribe un código de barras.',true);const p=db.products.find(p=>sameBarcode(p.code,code));if(!p){closeModal();if(confirm('Este código no está registrado. ¿Agregarlo como producto nuevo?'))askNewProduct(null,code);return}if(scanMode==='sell'){closeModal();addCart(p.id);go('sell');toast(p.name+' añadido a la venta.')}else showProduct(p.id)}
function addCart(id){const p=product(id);if(!p)return;if(p.stock<=num(cart[id]||0)){toast('No hay más unidades disponibles.',true);return}cart[id]=(cart[id]||0)+1;render()}
function checkout(){const entries=Object.entries(cart).filter(([id,q])=>product(id)&&q>0),total=sum(entries,([id,q])=>product(id).price*q);if(!entries.length)return;openModal('Cobrar venta',`<div class="card" style="box-shadow:none"><div class="stat-k">Total a cobrar</div><div class="stat-v">${money(total)}</div><div class="stat-note">${sum(entries,([,q])=>q)} piezas</div></div><div class="section-head"><h2>¿Cómo pagaron?</h2></div><div class="switches"><button class="active" data-act="sale-method" data-method="cash">Efectivo</button><button data-act="sale-method" data-method="transfer">Transferencia</button><button data-act="sale-method" data-method="credit">Fiado</button></div><input type="hidden" id="saleMethod" value="cash"><div id="saleMethodExtras">${field('¿Cuánto te entregaron?','cashGiven','number',total,'min="0" step="0.01" inputmode="decimal"')}<div class="helper" id="saleChange">Cambio: ${money(0)}</div></div>`, `<button class="btn btn-primary btn-block" data-act="complete-sale">Confirmar venta ${money(total)}</button>`)}
function changeSaleMethod(method){el('saleMethod').value=method;document.querySelectorAll('[data-act="sale-method"]').forEach(b=>b.classList.toggle('active',b.dataset.method===method));const total=sum(Object.entries(cart),([id,q])=>(product(id)?.price||0)*q);
el('saleMethodExtras').innerHTML=method==='cash'?`${field('¿Cuánto te entregaron?','cashGiven','number',total,'min="0" step="0.01" inputmode="decimal"')}<div class="helper" id="saleChange">Cambio: ${money(0)}</div>`:method==='credit'?db.customers.length?`${selectField('¿A qué cliente se le fía?','saleCustomer',db.customers)}<p class="helper">El importe completo se agregará a su saldo pendiente.</p>`:`<div class="notice warning">Primero crea al cliente en la sección Deudas.</div><button class="btn btn-outline btn-block" data-act="new-customer">Crear cliente</button>`:'<div class="notice">Se registrará como transferencia, sin aumentar el efectivo de caja.</div>'}
function completeSale(){const items=Object.entries(cart).filter(([id,q])=>product(id)&&q>0).map(([id,qty])=>{const p=product(id);return {productId:id,qty,price:p.price,cost:p.cost,name:p.name}});if(!items.length)return;for(const i of items){if(i.qty>product(i.productId).stock){toast('Cambió el inventario. Revisa la venta.',true);return}}
const method=inputVal('saleMethod'),total=num(sum(items,i=>i.qty*i.price));if(!needCash(method))return;
if(method==='cash'&&(!positive(inputVal('cashGiven'),true)||num(inputVal('cashGiven'))<total)){toast('El efectivo recibido no alcanza para cubrir la venta.',true);return}
let c=null;if(method==='credit'){c=customer(inputVal('saleCustomer'));if(!c){toast('Selecciona un cliente para el fiado.',true);return}}
const sale={id:uid(),items,total,method,customerId:c?.id||null,at:now()};db.sales.push(sale);for(const i of items){product(i.productId).stock-=i.qty;db.inventoryLogs.push({id:uid(),productId:i.productId,qty:-i.qty,reason:'Venta',at:sale.at})}if(method==='cash')cashEvent(total,'sale','Venta #'+sale.id.slice(0,6));if(c){c.debt=num(c.debt+total);db.customerMoves.push({id:uid(),customerId:c.id,type:'charge',amount:total,note:'Venta a crédito',at:now()})}
const change=method==='cash'?num(num(inputVal('cashGiven'))-total):0;save();cart={};closeModal();render();openModal('¡Venta registrada!',`<div style="text-align:center;padding:20px 0"><div style="font-size:58px;color:var(--brand)">✓</div><h2 style="margin:0">${money(total)}</h2><p class="muted small">${method==='credit'?'Se agregó al fiado del cliente':method==='cash'?`Cambio para entregar: ${money(change)}`:'Pago por transferencia'}</p></div>`,`<button class="btn btn-primary btn-block" data-act="close">Listo</button>`)}
function newPerson(kind){const client=kind==='customer';openModal(client?'Agregar cliente':'Agregar proveedor',`${field(client?'Nombre del cliente *':'Nombre del proveedor *','personName','text','','maxlength="80" placeholder="Nombre"')}${field('Teléfono (opcional)','personPhone','tel','','maxlength="30"')}${field(client?'Si ya te debe, escribe cuánto':'Si ya le debes, escribe cuánto','personDebt','number','0','min="0" step="0.01" inputmode="decimal"')}<div class="notice">Puedes comenzar en ${money(0)} e ir registrando ventas a crédito, pedidos y abonos.</div>`,`<button class="btn btn-primary btn-block" data-act="save-person" data-kind="${kind}">Guardar ${client?'cliente':'proveedor'}</button>`)}
function savePerson(kind){const name=inputVal('personName'),phone=inputVal('personPhone'),debt=num(inputVal('personDebt'));if(!name||!positive(inputVal('personDebt'),true)){toast('Completa el nombre y un saldo válido.',true);return}const id=uid(),o={id,name,phone,debt};if(kind==='customer'){db.customers.push(o);if(debt)db.customerMoves.push({id:uid(),customerId:id,type:'charge',amount:debt,note:'Saldo inicial',at:now()})}else{db.suppliers.push(o);if(debt)db.supplierMoves.push({id:uid(),supplierId:id,type:'charge',amount:debt,note:'Saldo inicial',at:now()})}save();closeModal();render();toast(`${kind==='customer'?'Cliente':'Proveedor'} guardado.`)}
function showPerson(id,kind){const client=kind==='customer',p=client?customer(id):supplier(id);if(!p)return;const movements=(client?db.customerMoves:db.supplierMoves).filter(m=>(client?m.customerId:m.supplierId)===id).sort((a,b)=>b.at.localeCompare(a.at));openModal(p.name,`<div class="card" style="box-shadow:none"><div class="stat-k">${client?'Te debe':'Le debes'}</div><div class="stat-v">${money(p.debt)}</div><div class="stat-note">${p.phone?h(p.phone):'Sin teléfono'}</div></div><div class="toolbar"><button class="btn btn-primary btn-block" data-act="pay" data-kind="${kind}" data-id="${id}">${client?'＋ Registrar abono':'− Registrar pago'}</button></div><div class="section-head"><h2>Movimientos</h2></div>${movements.length?`<div class="list">${movements.slice(0,40).map(m=>`<div class="list-row"><div class="grow"><div class="item-title">${h(m.note)}</div><div class="item-sub">${datePretty(m.at)} · ${timePretty(m.at)}</div></div><div class="item-price ${m.type==='charge'?'orange':'green'}">${m.type==='charge'?'+':'−'}${money(m.amount)}</div></div>`).join('')}</div>`:noData('✓','Sin movimientos','Los abonos y cargos aparecerán aquí.')}`)}
function paymentModal(kind,id){const client=kind==='customer',arr=client?db.customers:db.suppliers,person=id?(client?customer(id):supplier(id)):null;if(!arr.length){toast(`Primero registra un ${client?'cliente':'proveedor'}.`,true);return}const select=person?`<div class="notice">${h(person.name)} · saldo actual: <b>${money(person.debt)}</b></div>`:selectField(client?'Cliente':'Proveedor','paymentPerson',arr);openModal(client?'Recibir abono':'Pagar proveedor',`${select}${field('Cantidad *','paymentAmount','number',person?.debt||'','min="0.01" step="0.01" inputmode="decimal"')}${selectField('Forma de pago','paymentMethod',[{id:'cash',name:'Efectivo'},{id:'transfer',name:'Transferencia'}])}<p class="helper">El efectivo se suma o resta de la caja abierta. Las transferencias no modifican el efectivo.</p>`,`<button class="btn btn-primary btn-block" data-act="save-payment" data-kind="${kind}" data-id="${person?.id||''}">Guardar ${client?'abono':'pago'}</button>`)}
function savePayment(kind,id){const client=kind==='customer',p=client?customer(id||inputVal('paymentPerson')):supplier(id||inputVal('paymentPerson'));const amount=num(inputVal('paymentAmount')),method=inputVal('paymentMethod');if(!p||!positive(inputVal('paymentAmount'))||amount>num(p.debt)){toast('El abono debe ser mayor que cero y no exceder la deuda.',true);return}if(!needCash(method))return;p.debt=num(p.debt-amount);const move={id:uid(),type:'payment',amount,method,note:client?'Abono recibido':'Pago realizado',at:now()};if(client){db.customerMoves.push({...move,customerId:p.id});if(method==='cash')cashEvent(amount,'customer_payment','Abono: '+p.name)}else{db.supplierMoves.push({...move,supplierId:p.id});if(method==='cash')cashEvent(-amount,'supplier_payment','Pago a: '+p.name)}save();closeModal();render();toast(client?'Abono registrado.':'Pago registrado.')}
function beginOrder(){if(!db.suppliers.length){toast('Registra un proveedor antes de crear un pedido.',true);go('debts');debtTab='suppliers';render();newPerson('supplier');return}if(!db.products.length){toast('Primero agrega los productos que vas a pedir.',true);go('inventory');askNewProduct();return}orderDraft=[];openModal('Preparar pedido',`${selectField('Proveedor','orderSupplier',db.suppliers)}${field('Fecha estimada de llegada','orderArrival','date',localDay(new Date(Date.now()+86400000)))}${field('Fecha estimada de pago (opcional)','orderDue','date','')}<div class="hr"></div><div class="section-head"><h2>Productos que pedirás</h2></div>${selectField('Producto','orderItem',db.products.map(p=>({id:p.id,name:p.name+' · '+money(p.cost)})))}<div class="form-grid">${field('Cantidad','orderQty','number','1','min="1" step="1" inputmode="numeric"')}${field('Costo por unidad','orderUnitCost','number',db.products[0].cost,'min="0" step="0.01" inputmode="decimal"')}</div><button class="btn btn-outline btn-block" data-act="add-order-line">＋ Añadir al pedido</button><div id="draftZone"></div><div class="notice">Estos costos son estimados. Al confirmar que llegó el pedido, se sumarán las existencias y registrarás cómo se pagó.</div>`,`<button class="btn btn-primary btn-block" data-act="save-order">Guardar pedido</button>`);showDraft()}
function showDraft(){if(!el('draftZone'))return;el('draftZone').innerHTML=`<div class="order-draft">${orderDraft.length?orderDraft.map((i,index)=>`<div class="order-line"><div><b>${h(product(i.productId)?.name||'Producto')}</b><br><span class="muted">${i.qty} × ${money(i.unitCost)}</span></div><div style="text-align:right"><b>${money(i.qty*i.unitCost)}</b><br><button class="link" data-act="remove-order-line" data-index="${index}">Quitar</button></div></div>`).join(''):'<div class="helper">Aún no agregas productos.</div>'}<div class="total-row"><span>Total aproximado</span><strong>${money(sum(orderDraft,i=>i.qty*i.unitCost))}</strong></div></div>`}
function addOrderLine(){const p=product(inputVal('orderItem')),qty=Number(inputVal('orderQty')),cost=num(inputVal('orderUnitCost'));if(!p||!Number.isInteger(qty)||qty<1||!positive(inputVal('orderUnitCost'),true)){toast('Revisa producto, cantidad y costo.',true);return}const prev=orderDraft.find(i=>i.productId===p.id&&i.unitCost===cost);if(prev)prev.qty+=qty;else orderDraft.push({productId:p.id,qty,unitCost:cost});showDraft();el('orderQty').value='1';toast('Producto añadido al pedido.')}
function saveOrder(){const s=supplier(inputVal('orderSupplier')),date=inputVal('orderArrival');if(!s||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!orderDraft.length){toast('Elige proveedor, llegada y al menos un producto.',true);return}const items=orderDraft.map(i=>({...i,name:product(i.productId)?.name||'Producto'}));db.orders.push({id:uid(),supplierId:s.id,items,arrivalDate:date,dueDate:inputVal('orderDue'),total:num(sum(items,i=>i.qty*i.unitCost)),status:'pending',createdAt:now()});save();orderDraft=[];closeModal();go('orders');toast('Pedido preparado. Ya sabes cuánto gastarás.')}
function orderModal(id){const o=byId(db.orders,id);if(!o)return;const s=supplier(o.supplierId);openModal(o.status==='pending'?'Pedido por llegar':'Detalle del pedido',`<div class="card" style="box-shadow:none"><div class="stat-k">${h(s?.name||'Proveedor')}</div><div class="stat-v">${money(o.total)}</div><div class="stat-note">${o.status==='pending'?'Llega aproximadamente':'Llegada prevista'}: ${datePretty(o.arrivalDate)}${o.dueDate?' · Pago previsto: '+datePretty(o.dueDate):''}</div></div><div class="section-head"><h2>Productos</h2></div><div class="list">${o.items.map(i=>`<div class="list-row"><div class="grow"><div class="item-title">${h(i.name)}</div><div class="item-sub">${i.qty} × ${money(i.unitCost)}</div></div><div class="item-price">${money(i.qty*i.unitCost)}</div></div>`).join('')}</div>${o.status==='pending'?`<div class="notice">Confirma la recepción solo cuando realmente haya llegado la mercancía.</div><button class="btn btn-primary btn-block" data-act="receive" data-id="${id}">✓ Recibir mercancía</button><button class="btn btn-danger btn-block" style="margin-top:8px" data-act="cancel-order" data-id="${id}">Cancelar pedido</button>`:`<div class="notice">Estado: ${o.status==='received'?'recibido':'cancelado'}. ${o.status==='received'?'Pago: '+(o.method==='credit'?'A crédito':o.method==='cash'?'Efectivo':'Transferencia'):''}</div>`}`)}
function receiveModal(id){const o=byId(db.orders,id);if(!o||o.status!=='pending')return;openModal('Recibir pedido',`<div class="notice"><b>${h(supplier(o.supplierId)?.name||'Proveedor')}</b><br>${o.items.length} productos · total ${money(o.total)}</div>${selectField('¿Cómo pagaste la mercancía?','receiveMethod',[{id:'credit',name:'A crédito (queda deuda)'},{id:'cash',name:'Efectivo de caja'},{id:'transfer',name:'Transferencia'}])}<p class="helper">Si seleccionas crédito, el total se agregará a la deuda con este proveedor. Si eliges efectivo, se descontará del corte de caja.</p>`,`<button class="btn btn-primary btn-block" data-act="confirm-receive" data-id="${id}">Confirmar recepción y actualizar inventario</button>`)}
function confirmReceive(id){const o=byId(db.orders,id);if(!o||o.status!=='pending')return;const method=inputVal('receiveMethod');if(!['credit','cash','transfer'].includes(method)||!needCash(method))return;for(const i of o.items){if(!product(i.productId)){toast('Un producto de este pedido ya no existe.',true);return}}
for(const i of o.items){const p=product(i.productId);p.stock+=i.qty;p.cost=i.unitCost;db.inventoryLogs.push({id:uid(),productId:p.id,qty:i.qty,reason:'Pedido recibido',at:now()})}o.status='received';o.receivedAt=now();o.method=method;const s=supplier(o.supplierId);if(method==='credit'&&s){s.debt=num(s.debt+o.total);db.supplierMoves.push({id:uid(),supplierId:s.id,type:'charge',amount:o.total,note:'Pedido recibido'+(o.dueDate?' · vence '+o.dueDate:''),dueDate:o.dueDate,at:now()})}if(method==='cash')cashEvent(-o.total,'purchase','Compra a '+(s?.name||'proveedor'));save();closeModal();render();toast('Mercancía recibida e inventario actualizado.')}
function cancelOrder(id){const o=byId(db.orders,id);if(!o||o.status!=='pending')return;if(!confirm('¿Cancelar este pedido pendiente? No afectará inventario ni deudas.'))return;o.status='cancelled';save();closeModal();render();toast('Pedido cancelado.')}
function cashModal(){const s=openSession();if(!s){openModal('Abrir caja',`<div class="notice">Pon el efectivo que ya tienes en la caja al iniciar. No se considera una venta.</div>${field('¿Con cuánto dinero empiezas?','cashOpening','number','0','min="0" step="0.01" inputmode="decimal"')}`,`<button class="btn btn-primary btn-block" data-act="open-cash">Abrir caja</button>`);return}
const moves=db.cashMovements.filter(m=>m.sessionId===s.id).sort((a,b)=>b.at.localeCompare(a.at));const cashSales=sum(moves.filter(m=>m.kind==='sale'),m=>m.amount);const inflows=sum(moves.filter(m=>m.amount>0),m=>m.amount);const outflows=sum(moves.filter(m=>m.amount<0),m=>-m.amount);
openModal('Mi caja',`<div class="card" style="box-shadow:none"><div class="stat-k">Efectivo esperado</div><div class="stat-v">${money(cashExpected(s))}</div><div class="stat-note">Caja abierta ${datePretty(s.openedAt)} a las ${timePretty(s.openedAt)}</div></div><div class="metric-strip"><div class="chip">Fondo inicial<strong>${money(s.initial)}</strong></div><div class="chip">Ventas en efectivo<strong>${money(cashSales)}</strong></div><div class="chip">Entradas adicionales<strong>${money(inflows-cashSales)}</strong></div><div class="chip">Salidas<strong>${money(outflows)}</strong></div></div><div class="two-buttons"><button class="btn btn-soft" data-act="expense">− Registrar gasto</button><button class="btn btn-outline" data-act="cash-adjust">＋ / − Efectivo</button></div><div class="section-head"><h2>Movimientos del turno</h2></div>${moves.length?`<div class="list">${moves.slice(0,35).map(m=>`<div class="list-row"><div class="grow"><div class="item-title">${h(m.note)}</div><div class="item-sub">${timePretty(m.at)} · ${datePretty(m.at)}</div></div><div class="item-price ${m.amount<0?'red':'green'}">${m.amount<0?'−':'+'}${money(Math.abs(m.amount))}</div></div>`).join('')}</div>`:noData('↔','Sin movimientos','Los cobros en efectivo y las salidas aparecerán aquí.')}`,`<button class="btn btn-primary btn-block" data-act="close-cash">Hacer corte de caja</button>`)}
function openCash(){if(!positive(inputVal('cashOpening'),true)){toast('Escribe una cantidad válida.',true);return}if(openSession())return;db.cashSessions.push({id:uid(),openedAt:now(),initial:num(inputVal('cashOpening')),closedAt:null});save();closeModal();render();toast('Caja abierta. ¡Buen día de ventas!')}
function closeCashModal(){const s=openSession();if(!s)return;const expected=cashExpected(s);openModal('Corte de caja',`<div class="card" style="box-shadow:none"><div class="stat-k">Efectivo que debería haber</div><div class="stat-v">${money(expected)}</div><p class="helper">Cuenta los billetes y monedas físicamente, y escribe el total real.</p></div>${field('Efectivo contado en caja *','cashCount','number',Math.max(0,expected),'min="0" step="0.01" inputmode="decimal"')}<div class="notice" id="cashDifference">Diferencia: ${money(0)}</div><div class="notice warning">Al cerrar, el turno quedará guardado y deberás abrir una caja nueva para recibir efectivo.</div>`,`<button class="btn btn-primary btn-block" data-act="confirm-close-cash">Cerrar caja y guardar corte</button>`)}
function confirmCloseCash(){const s=openSession();if(!s||!positive(inputVal('cashCount'),true))return toast('El efectivo contado debe ser válido.',true);const counted=num(inputVal('cashCount'));s.expected=cashExpected(s);s.counted=counted;s.difference=num(counted-s.expected);s.closedAt=now();save();closeModal();render();openModal('Corte guardado',`<div style="text-align:center;padding:12px"><div style="font-size:48px;color:var(--brand)">✓</div><h2>${s.difference===0?'¡Caja cuadrada!':s.difference>0?'Sobrante de caja':'Faltante de caja'}</h2><div class="stat-v ${s.difference===0?'green':s.difference<0?'red':'orange'}">${money(s.difference)}</div><p class="helper">Esperado: ${money(s.expected)} · Contado: ${money(s.counted)}</p></div>`,`<button class="btn btn-primary btn-block" data-act="close">Entendido</button>`)}
function expenseModal(){openModal('Registrar gasto',`${field('¿En qué gastaste?','expenseName','text','','placeholder="Ej. Bolsas, luz, limpieza" maxlength="100"')}${field('¿Cuánto gastaste?','expenseAmount','number','','min="0.01" step="0.01" inputmode="decimal"')}${selectField('Forma de pago','expenseMethod',[{id:'cash',name:'Efectivo'},{id:'transfer',name:'Transferencia'}])}`,`<button class="btn btn-primary btn-block" data-act="save-expense">Guardar gasto</button>`)}
function saveExpense(){const name=inputVal('expenseName'),amount=num(inputVal('expenseAmount')),method=inputVal('expenseMethod');if(!name||!positive(inputVal('expenseAmount'))){toast('Revisa la descripción y cantidad.',true);return}if(!needCash(method))return;db.expenses.push({id:uid(),name,amount,method,at:now()});if(method==='cash')cashEvent(-amount,'expense','Gasto: '+name);save();closeModal();render();toast('Gasto registrado.')}
function cashAdjustModal(){openModal('Ajustar efectivo',`${selectField('Tipo de movimiento','cashAdjustKind',[{id:'in',name:'Agregar efectivo a caja'},{id:'out',name:'Retirar efectivo de caja'}])}${field('Cantidad','cashAdjustAmount','number','','min="0.01" step="0.01" inputmode="decimal"')}${field('Motivo','cashAdjustReason','text','','maxlength="120" placeholder="Ej. Cambio para caja"')}<p class="helper">Estos movimientos no se registran como ventas ni como gastos comerciales.</p>`,`<button class="btn btn-primary btn-block" data-act="save-adjust">Guardar movimiento</button>`)}
function saveAdjust(){const amount=num(inputVal('cashAdjustAmount')),kind=inputVal('cashAdjustKind'),reason=inputVal('cashAdjustReason');const s=openSession();if(!s){toast('No hay caja abierta.',true);return}if(!positive(inputVal('cashAdjustAmount'))||!reason){toast('Ingresa cantidad y motivo.',true);return}cashEvent(kind==='in'?amount:-amount,'adjust',reason);save();closeModal();render();toast('Movimiento registrado.')}
function settingsModal(){const closed=db.cashSessions.filter(s=>!!s.closedAt).sort((a,b)=>b.closedAt.localeCompare(a.closedAt));openModal('Ajustes y respaldo',`<div class="notice"><b>Datos:</b> ${typeof cloudEnabled==='function'&&cloudEnabled()?'Conectados a Firebase Firestore. Los cambios se sincronizan cuando el indicador confirma «Guardado en Firebase».':'Para comenzar, configura Firebase y entra con tu cuenta privada.'}</div>${typeof cloudConflict==='boolean'&&cloudConflict?'<div class="notice warning">Conflicto: hay cambios en este celular que no coinciden con Firebase. Primero exporta respaldo, después puedes descartar los cambios locales.</div><button class="btn btn-danger btn-block" data-act="resolve-conflict">Restablecer desde Firebase (descartar cambios locales)</button>':''}<button class="btn btn-outline btn-block" data-act="cloud-retry">↻ Sincronizar ahora</button><button class="btn btn-outline btn-block" data-act="logout" style="margin-top:8px">⇥ Cerrar sesión</button><div class="section-head"><h2>Tus datos</h2></div><div class="card" style="box-shadow:none"><div class="measure"><span>Productos</span><b>${db.products.length}</b></div><div class="measure"><span>Ventas</span><b>${db.sales.length}</b></div><div class="measure"><span>Clientes / proveedores</span><b>${db.customers.length} / ${db.suppliers.length}</b></div></div><div class="toolbar"><button class="btn btn-primary" data-act="export">↓ Descargar respaldo</button><label class="btn btn-outline" for="importFile" style="cursor:pointer">↑ Restaurar respaldo</label><input type="file" accept="application/json,.json" id="importFile" class="sr-only"></div><div class="section-head"><h2>Cortes anteriores</h2></div>${closed.length?`<div class="list">${closed.slice(0,15).map(s=>`<div class="list-row"><div class="grow"><div class="item-title">${datePretty(s.closedAt)}</div><div class="item-sub">Esperado ${money(s.expected)} · contado ${money(s.counted)}</div></div><span class="item-price ${s.difference<0?'red':'green'}">${money(s.difference)}</span></div>`).join('')}</div>`:noData('✓','Aún no hay cortes','Los cortes cerrados quedarán aquí para consultarlos.')}
<p class="helper">Acceso privado con Firebase Authentication. Los cambios pendientes solo están en este celular; guarda respaldos periódicos.</p>`)}
function exportDb(){const blob=new Blob([JSON.stringify({...db,exportedAt:now()},null,2)],{type:'application/json'}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=`super-la-muneca-respaldo-${localDay()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),15000);toast('Respaldo descargado. Guárdalo en un lugar seguro.')}
async function importDb(file){if(!file)return;if(typeof cloudCanEdit==='function'&&!cloudCanEdit('import')){toast('Primero resuelve la sincronización antes de restaurar un respaldo.',true);return}try{const data=JSON.parse(await file.text());if(!validDb(data))throw Error('Formato no válido');if(!confirm('Esto reemplazará TODOS los datos actuales por los del respaldo. ¿Continuar?'))return;db=data;save();cart={};closeModal();go('home');toast('Respaldo restaurado correctamente.')}catch(e){toast('El archivo no es un respaldo válido.',true)}}
function updateSearch(id,v){if(id==='inventorySearch')filterProducts=v;else sellFilter=v;const elem=el(id),pos=elem?.selectionStart;render();const newElem=el(id);newElem?.focus();try{newElem?.setSelectionRange(pos,pos)}catch(e){}}
function safeRun(fn){try{fn()}catch(e){console.error('Error de la aplicación:',e);toast('Ocurrió un problema. Revisa la conexión y tu respaldo.',true)}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-act]');if(!a){if(e.target.classList.contains('modal-overlay'))closeModal();return}const act=a.dataset.act,id=a.dataset.id,kind=a.dataset.kind;
if(typeof cloudCanEdit==='function'&&!cloudCanEdit(act)){toast('Sincronización bloqueada. Revisa Ajustes y tu conexión.',true);return}
safeRun(()=>{switch(act){case 'nav':go(a.dataset.tab);break;case 'settings':settingsModal();break;case 'cloud-retry':if(typeof cloudRetry==='function')cloudRetry();break;case 'logout':if(typeof cloudLogout==='function')cloudLogout();break;case 'resolve-conflict':if(typeof cloudResolveConflict==='function')cloudResolveConflict();break;case 'close':closeModal();break;
case 'new-product':askNewProduct();break;case 'save-product':saveProduct(id);break;case 'product':showProduct(id);break;case 'product-edit':askNewProduct(product(id));break;case 'barcode':case 'qr':showBarcode(id);break;case 'print':window.print();break;case 'stock':stockModal(id);break;case 'change-stock':changeStock(id,Number(a.dataset.sign));break;case 'scan':scannerModal('inventory');break;case 'scan-sale':scannerModal('sell');break;case 'camera-start':startCamera();break;case 'lookup-qr':lookupCode(inputVal('scanText'));break;
case 'cart-add':addCart(id);break;case 'cart-sub':cart[id]=Math.max(0,(cart[id]||0)-1);if(!cart[id])delete cart[id];render();break;case 'cart-direct':addCart(id);closeModal();go('sell');break;case 'cart-clear':cart={};render();break;case 'checkout':checkout();break;case 'sale-method':changeSaleMethod(a.dataset.method);break;case 'complete-sale':completeSale();break;
case 'debt-tab':debtTab=kind;render();break;case 'new-customer':newPerson('customer');break;case 'new-supplier':newPerson('supplier');break;case 'save-person':savePerson(kind);break;case 'customer':showPerson(id,'customer');break;case 'supplier':showPerson(id,'supplier');break;case 'payment-customer':paymentModal('customer');break;case 'payment-supplier':paymentModal('supplier');break;case 'pay':paymentModal(kind,id);break;case 'save-payment':savePayment(kind,id);break;
case 'order-tab':orderTab=kind;render();break;case 'new-order':beginOrder();break;case 'add-order-line':addOrderLine();break;case 'remove-order-line':orderDraft.splice(Number(a.dataset.index),1);showDraft();break;case 'save-order':saveOrder();break;case 'order':orderModal(id);break;case 'receive':receiveModal(id);break;case 'confirm-receive':confirmReceive(id);break;case 'cancel-order':cancelOrder(id);break;
case 'cash':cashModal();break;case 'open-cash':openCash();break;case 'close-cash':closeCashModal();break;case 'confirm-close-cash':confirmCloseCash();break;case 'expense':expenseModal();break;case 'save-expense':saveExpense();break;case 'cash-adjust':cashAdjustModal();break;case 'save-adjust':saveAdjust();break;case 'export':exportDb();break;
}})});
document.addEventListener('input',e=>{if(e.target.id==='inventorySearch'||e.target.id==='sellSearch')updateSearch(e.target.id,e.target.value);if(e.target.id==='cashCount'){const s=openSession();if(s&&el('cashDifference')){const d=num(num(e.target.value)-cashExpected(s));el('cashDifference').textContent=`Diferencia: ${money(d)} ${d<0?'(faltante)':d>0?'(sobrante)':'(cuadrada)'}`}}if(e.target.id==='cashGiven'&&el('saleChange')){const total=sum(Object.entries(cart),([id,q])=>(product(id)?.price||0)*q);el('saleChange').textContent=`Cambio: ${money(Math.max(0,num(e.target.value)-total))}`}});
document.addEventListener('change',e=>{if(e.target.id==='importFile')importDb(e.target.files?.[0]);if(e.target.id==='orderItem'){const p=product(e.target.value);if(p&&el('orderUnitCost'))el('orderUnitCost').value=p.cost}if(e.target.id==='scanPhoto'&&e.target.files?.[0])scanFromPhoto(e.target.files[0])});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&el('modalRoot').firstChild)closeModal();if(e.key==='Enter'&&e.target.id==='scanText'){e.preventDefault();lookupCode(inputVal('scanText'))}});
if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(e=>console.debug('Sin modo offline',e));
if(typeof cloudInit==='function')cloudInit()
